    /// <summary>
    /// Default collapse set for huge plans: subtrees whose total cost fraction is below
    /// <paramref name="costThreshold"/> are collapsed until ~<paramref name="maxAutoExpandedNodes"/> stay visible.
    /// </summary>
    public static HashSet<int> ComputeDefaultCollapsed(PlanStatement statement, double costThreshold = 0.01, int maxAutoExpandedNodes = 300)
    {
        var collapsed = new HashSet<int>();
        if (statement.Root is null || statement.AllNodes.Count <= maxAutoExpandedNodes)
            return collapsed;

        // Collapse cheap subtrees bottom-up until the visible count is within budget.
        foreach (var node in statement.AllNodes.OrderBy(n => SubtreeCostFraction(n)))
        {
            if (CountVisible(statement.Root, collapsed) <= maxAutoExpandedNodes)
                break;
            if (node.Children.Count > 0 && SubtreeCostFraction(node) < costThreshold)
                collapsed.Add(node.NodeId);
        }

        return collapsed;

        static double SubtreeCostFraction(PlanNode node)
        {
            var total = node.CostFraction;
            foreach (var child in node.Children)
                total += SubtreeCostFraction(child);
            return total;
