                VALUES (@sha, @queryPlanHash, @gzip, @bytes, SYSUTCDATETIME())
            WHEN MATCHED THEN UPDATE SET QueryPlanHash = ISNULL(t.QueryPlanHash, @queryPlanHash)
            OUTPUT inserted.Id;
            """,
            new { sha, queryPlanHash, gzip = compressed, bytes = Encoding.UTF8.GetByteCount(masked) },
            cancellationToken: ct)).ConfigureAwait(false);

        cache[cacheKey] = id;
        return id;
    }

