eading keys are a permutation
    /// of the equality columns, followed by the inequality columns in order, and its key+include
    /// set covers the requested included columns.
    /// </summary>
    internal static bool Subsumes(ExistingIndex index, IReadOnlyList<string> equality, IReadOnlyList<string> inequality, IReadOnlyList<string> included)
    {
        var keys = Columns(index.KeyColumns);
        if (keys.Count < equality.Count + inequality.Count)
            return false;

        // Leading keys must cover all equality columns (order within the equality set doesn't matter).
        var leading = keys.Take(equality.Count).ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (!equality.All(leading.Contains))
            return false;

        // Inequality columns must follow, in order.
        var after = keys.Skip(equality.Count).Take(inequality.Count).ToList();
        if (!inequality.SequenceEqual(after, StringComparer.OrdinalIgnoreCase))
            return false;

        // Includes can be satisfied by keys or include columns.
        var covered = keys.Concat(Columns(index.IncludeColumns)).ToHashSet(StringComparer.OrdinalIgnoreCase);
        return included.All(covered.Contains);
    }

    internal static bool SharesLeadingKey(ExistingIndex index, IReadOnlyList<string> requestedKeys)
    {
        var keys = Columns(index.KeyColumns);
        return keys.Count > 0 && requestedKeys.Count > 0 &&
               string.Equals(keys[0], requestedKeys[0], StringComparison.OrdinalIgnoreCase);
    }

